-- drops: only work_order_crews insert/update admit Planner within existing organisation scope; crew membership/master policies unchanged. Field policy remains restrictive (1480).
alter policy work_order_crews_insert on public.work_order_crews with check (org_id=(select public.auth_org_id()) and (select public.is_active_member()) and ((select public.crew_can_manage()) or (not (select public.actor_is_light()) and (select public.actor_holds_job_role('planner')))));
alter policy work_order_crews_update on public.work_order_crews using (org_id=(select public.auth_org_id()) and (select public.is_active_member()) and ((select public.crew_can_manage()) or (not (select public.actor_is_light()) and (select public.actor_holds_job_role('planner'))))) with check (org_id=(select public.auth_org_id()) and (select public.is_active_member()));
